  so.c0 = vec4f(C[0], flow); so.c1 = vec4f(C[1], soak); so.c2 = vec4f(C[2], mix(so.c2.w, passing, 0.05));
  solids[sid] = so;
  // (A sand particle's material carries how wet it is, for the draw: 5 dry to 5.9 soaked. Snow's too: 6 to 6.4.)
  var kind = select(x4.w, 5.0 + 0.9 * clamp((bound + 0.36 * wetNodes) / 0.5, 0.0, 1.0), isSand(x4.w));
  if (isSnow(x4.w)) {
    kind = 6.0 + 0.4 * soak;
  }
  if (isMud(x4.w)) { kind = 7.0 + 0.4 * soak; }   // (and mud's: 7 to 7.4)
  if (isLava(x4.w)) { kind = 8.0 + 0.4 * soak; }
